/* eslint-disable @typescript-eslint/no-explicit-any */
import fs from "node:fs";
import path from "node:path";
import type {
  HTTPMethod,
  McpTool,
  NavigationGroup,
  OpenAPISpec,
  ParsedEndpoint,
  RestRoute,
  SearchItem,
} from "./types";
import { resolveRefs } from "./resolve-refs";

// Generated artifacts — see scripts/gen-api-docs.py. Committed to the repo and
// regenerated by the Pages workflow before this app is built.
const API_DIR = path.join(process.cwd(), "..", "landing", "api");

function readJSON<T>(file: string, fallback: T): T {
  const p = path.join(API_DIR, file);
  if (!fs.existsSync(p)) return fallback;
  return JSON.parse(fs.readFileSync(p, "utf8")) as T;
}

/** Host port for the local REST API server (MicropodAPIMain default). */
export const REST_BASE_URL = "http://localhost:45454";

// ---------------------------------------------------------------------------
// REST routes (rest-routes.json — extracted from APIHandlers.swift)
// ---------------------------------------------------------------------------

function restGroup(p: string): string {
  if (p === "/health" || p === "/metrics") return "Service";
  const seg = p.split("/").filter(Boolean)[1] ?? "other";
  const names: Record<string, string> = {
    containers: "Containers",
    images: "Images",
    volumes: "Volumes",
    networks: "Networks",
    compose: "Compose",
    system: "System",
    config: "Config",
    stats: "Stats",
    usage: "Usage",
    exec: "Exec",
  };
  return names[seg] ?? seg[0].toUpperCase() + seg.slice(1);
}

export function restRouteId(method: string, p: string): string {
  const slug = p
    .replace(/\//g, "-")
    .replace(/[{}]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
  return `${method.toLowerCase()}-${slug}`;
}

export function loadRestRoutes(): RestRoute[] {
  const raw = readJSON<Array<{ method: string; path: string; description: string }>>(
    "rest-routes.json",
    [],
  );
  return raw.map((r) => ({
    id: restRouteId(r.method, r.path),
    method: r.method as HTTPMethod,
    path: r.path,
    description: r.description,
    group: restGroup(r.path),
    pathParams: [...r.path.matchAll(/\{(\w+)\}/g)].map((m) => m[1]),
  }));
}

export function getRestRoute(id: string): RestRoute | undefined {
  return loadRestRoutes().find((r) => r.id === id);
}

// ---------------------------------------------------------------------------
// MCP tools (mcp-tools.json — captured from a live tools/list)
// ---------------------------------------------------------------------------

const MCP_GROUP_ORDER = [
  "containers",
  "images",
  "volumes",
  "shares",
  "networks",
  "compose",
  "system",
  "cache",
];

function mcpGroup(name: string): string {
  if (name.startsWith("compose")) return "compose";
  if (name.startsWith("share")) return "shares";
  if (name.startsWith("volume") || name === "df") return "volumes";
  if (name.startsWith("list_image") || name === "pull" || name === "push") return "images";
  if (name.startsWith("list_network")) return "networks";
  if (name.startsWith("update") || name === "status" || name === "stats") return "system";
  if (name === "build_cache_stats") return "cache";
  return "containers";
}

export function loadMcpTools(): McpTool[] {
  const raw = readJSON<Array<{ name: string; description?: string; inputSchema?: any }>>(
    "mcp-tools.json",
    [],
  );
  return raw
    .map((t) => ({
      name: t.name,
      description: t.description ?? "",
      inputSchema: t.inputSchema ?? {},
      group: mcpGroup(t.name),
    }))
    .sort((a, b) => a.name.localeCompare(b.name));
}

export function mcpGroups(tools: McpTool[]): { title: string; tools: McpTool[] }[] {
  const map = new Map<string, McpTool[]>();
  for (const t of tools) {
    const list = map.get(t.group) ?? [];
    list.push(t);
    map.set(t.group, list);
  }
  return MCP_GROUP_ORDER.filter((g) => map.has(g)).map((g) => ({
    title: g[0].toUpperCase() + g.slice(1),
    tools: map.get(g)!,
  }));
}

export function getMcpTool(name: string): McpTool | undefined {
  return loadMcpTools().find((t) => t.name === name);
}

