export interface ConnectService {
  file: string;
  service: string;
  title: string;
  blurb: string;
  spec: OpenAPISpec;
}

/** Last segment of the first `content[*].schema.$ref` — the proto type name. */
function schemaRefName(node: any): string | undefined {
  const content = node?.content ?? {};
  for (const v of Object.values<any>(content)) {
    const ref = v?.schema?.$ref;
    if (typeof ref === "string") return ref.split("/").pop();
  }
  return undefined;
}

function parseSpec(file: string): OpenAPISpec {
  const raw = readJSON<any>(file, null);
  if (!raw) {
    return {
      file,
      info: { title: "API", version: "0" },
      endpoints: [],
      groups: [],
      schemaCount: 0,
    };
  }

  const schemas = raw.components?.schemas ?? {};
  const endpoints: ParsedEndpoint[] = [];

  for (const [pathKey, methods] of Object.entries<any>(raw.paths ?? {})) {
    for (const [method, operation] of Object.entries<any>(methods)) {
      if (typeof operation !== "object") continue;
      const service = (operation.tags?.[0] as string | undefined) ?? "unknown";
      // Capture proto message type names before resolveRefs dereferences them —
      // SDK samples need e.g. "micropod.v1.RunContainerRequest".
      const requestType = schemaRefName(operation.requestBody);
      const okContent = operation.responses?.["200"]?.content ?? {};
      const responseType = schemaRefName(operation.responses?.["200"]);
      const serverStreaming = Object.keys(okContent).some(
        (ct) => ct.includes("connect+") || ct.includes("grpc"),
      );
      endpoints.push({
        id: `${method}-${pathKey.replace(/\//g, "-").replace(/[{}]/g, "")}`.toLowerCase(),
        method: method.toUpperCase() as HTTPMethod,
        path: pathKey,
        service,
        summary: operation.summary,
        description: operation.description,
        operationId: operation.operationId,
        requestType,
        responseType,
        serverStreaming,
        parameters: resolveRefs(operation.parameters ?? [], schemas),
        requestBody: resolveRefs(operation.requestBody, schemas),
        responses: resolveRefs(operation.responses ?? {}, schemas),
      });
    }
  }

  const byService = new Map<string, ParsedEndpoint[]>();
  for (const e of endpoints) {
    const list = byService.get(e.service) ?? [];
    list.push(e);
    byService.set(e.service, list);
  }
  const groups: NavigationGroup[] = [...byService.entries()].map(([svc, eps]) => ({
    title: svc.split(".").pop() ?? svc,
    endpoints: eps,
  }));

  return {
    file,
    info: {
      title: raw.info?.title ?? file,
      description: raw.info?.description,
      version: raw.info?.version ?? "0",
    },
    endpoints,
    groups,
    schemaCount: Object.keys(schemas).length,
  };
}

export function loadConnectServices(): ConnectService[] {
  return CONNECT_SPECS.map((s) => ({ ...s, spec: parseSpec(s.file) }));
}

export function getConnectEndpoint(id: string): {
  endpoint: ParsedEndpoint;
  service: ConnectService;
} | undefined {
  for (const service of loadConnectServices()) {
    const endpoint = service.spec.endpoints.find((e) => e.id === id);
    if (endpoint) return { endpoint, service };
  }
  return undefined;
}

/** Pre-split page ids were `…-micropodservice-<method>`; resolve them to the
 * endpoint's current id so old /grpc/ links redirect instead of 404ing. */
export function legacyConnectEndpointId(id: string): string | undefined {
  const m = id.match(/^(\w+)--api-micropod\.v1\.micropodservice-(\w+)$/);
  if (!m) return undefined;
  const [, , methodSlug] = m;
  for (const svc of loadConnectServices()) {
    const hit = svc.spec.endpoints.find(
      (e) => e.path.split("/").pop()?.toLowerCase() === methodSlug,
    );
    if (hit) return hit.id;
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Search index (all surfaces, for the header Cmd+K dialog)
// ---------------------------------------------------------------------------

export function buildSearchIndex(): SearchItem[] {
  const items: SearchItem[] = [
    {
      kind: "SDK",
      title: "Client SDKs",
      subtitle: "Go, TypeScript, and Swift clients — retry, timeouts, OpenTelemetry",
      href: "/sdk/",
    },
  ];
  for (const svc of loadConnectServices()) {
    for (const e of svc.spec.endpoints) {
      items.push({
        kind: svc.service.startsWith("micropod.") ? "API" : "Guest",
        title: e.summary ?? e.path,
        subtitle: `${svc.title} · ${e.description ?? ""}`.trim(),
        href: `/grpc/${e.id}/`,
        method: e.method,
      });
    }
  }
  for (const t of loadMcpTools()) {
    items.push({
      kind: "MCP",
      title: t.name,
      subtitle: t.description,
      href: `/mcp/${t.name}/`,
    });
  }
  return items;
}
